<?php use AlbaTech\Core\View; ?>
<div class="admin-page-actions"><p>Manage published case studies and featured work shown on the public website.</p><a class="button button--primary" href="/admin/work/create"><i class="fa-solid fa-plus" aria-hidden="true"></i> Add project</a></div>
<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Project</th><th>Category</th><th>Order</th><th>Status</th><th>Homepage</th><th>Actions</th></tr></thead><tbody>
<?php if (empty($projects)): ?><tr><td colspan="6">No projects yet. Add your first project to start building the portfolio.</td></tr><?php endif; ?>
<?php foreach ($projects as $project): ?><tr><td><div class="work-admin-project"><?php if (!empty($project['cover_image'])): ?><img src="/<?= View::escape(ltrim($project['cover_image'],'/')) ?>" alt="" loading="lazy"><?php endif; ?><div><strong><?= View::escape($project['title']) ?></strong><small>/work/<?= View::escape($project['slug']) ?></small></div></div></td><td><?= View::escape($project['category_name']) ?></td><td><?= (int)$project['sort_order'] ?></td><td><span class="status-pill status-pill--<?= View::escape($project['status']) ?>"><?= View::escape(ucfirst($project['status'])) ?></span></td><td><?= (int)$project['is_featured']===1?'Featured':'—' ?></td><td><div class="table-actions"><a class="button button--small button--secondary" href="/admin/work/<?= (int)$project['id'] ?>/edit">Edit</a><?php if ($project['status']==='published'): ?><a class="button button--small button--secondary" href="/work/<?= rawurlencode($project['slug']) ?>" target="_blank" rel="noopener">View</a><?php endif; ?><form method="post" action="/admin/work/<?= (int)$project['id'] ?>/delete" data-confirm="Delete this project and its cover image?"><input type="hidden" name="_csrf" value="<?= View::escape($csrf) ?>"><button class="button button--small button--danger" type="submit">Delete</button></form></div></td></tr><?php endforeach; ?>
</tbody></table></div>
